/**
 * webpack loader: generates the CSS of the Bootstrap Icons used by the web UI, from the SVG files of the Debian
 * package bootstrap-icons (/usr/share/bootstrap-icons/svg). Debian has no icon font, so each icon is an SVG mask:
 *
 *   <i className="bi bi-trash" />   →   .bi-trash { --bi: url("data:image/svg+xml;base64,...") }
 *
 * The icon names are collected from web/src (every "bi-<name>"), so only the icons in use end up in main.css.
 * The ::before box is 1em × 1em in the text colour, like the font glyph; font-size and color work as before.
 * Used for the import of src/bootstrap-icons.css (see webpack.config.js); the file itself is a placeholder.
 */
const fs = require('fs');
const path = require('path');

// Debian package first, npm package (`npm install bootstrap-icons`) as fallback outside Debian.
const SVG_DIRS = [
  '/usr/share/bootstrap-icons/svg',
  path.resolve(__dirname, 'node_modules/bootstrap-icons/icons'),
];

function sourceFiles(dir) {
  return fs.readdirSync(dir, { withFileTypes: true }).flatMap((e) => {
    const p = path.join(dir, e.name);
    if (e.isDirectory()) return sourceFiles(p);
    return /\.(jsx?|css)$/.test(e.name) && e.name !== 'bootstrap-icons.css' ? [p] : [];
  });
}

module.exports = function bootstrapIconsLoader() {
  const srcDir = path.resolve(__dirname, 'src');
  this.addContextDependency(srcDir);

  const svgDir = SVG_DIRS.find((d) => fs.existsSync(d));
  if (!svgDir) {
    throw new Error(`bootstrap icons not found in ${SVG_DIRS.join(' or ')} (install the Debian package bootstrap-icons)`);
  }

  const names = new Set();
  for (const file of sourceFiles(srcDir)) {
    for (const m of fs.readFileSync(file, 'utf8').matchAll(/\bbi-([a-z0-9]+(?:-[a-z0-9]+)*)/g)) {
      names.add(m[1]);
    }
  }

  const missing = [...names].filter((n) => !fs.existsSync(path.join(svgDir, `${n}.svg`)));
  if (missing.length) {
    throw new Error(`bootstrap icons not found in ${svgDir}: ${missing.sort().join(', ')}`);
  }

  const rules = [...names].sort().map((n) => {
    const svg = fs.readFileSync(path.join(svgDir, `${n}.svg`));
    return `.bi-${n} { --bi: url("data:image/svg+xml;base64,${svg.toString('base64')}"); }`;
  });

  return `/* Bootstrap Icons (${names.size} used) from ${svgDir}, generated by bootstrap-icons-loader.js */
[class^="bi-"]::before,
[class*=" bi-"]::before {
  content: "";
  display: inline-block;
  width: 1em;
  height: 1em;
  vertical-align: -.125em;
  background-color: currentColor;
  -webkit-mask: var(--bi) no-repeat center / contain;
  mask: var(--bi) no-repeat center / contain;
}
${rules.join('\n')}
`;
};
